+    }
+
+    @Override
+    public UnaryPlan replaceChild(LogicalPlan newChild) {
+        return new ChangePoint(source(), newChild, value, key, targetType, targetPvalue);
+    }
+
+    @Override
+    public List<Attribute> output() {
