+        super(source, child);
+        this.insistedAttributes = insistedAttributes;
+    }
+
+    @Override
+    public List<Attribute> output() {
+        if (lazyOutput == null) {
+            lazyOutput = NamedExpressions.mergeOutputAttributes(insistedAttributes, child().output());
